```python
import asyncio

from fastmcp import FastMCP, Client


mcp = FastMCP("ConfigServer")


@mcp.resource("data://config")
def get_config() -> dict:
    return {"debug": True, "version": "1.0.0"}


async def main() -> None:
    client = Client(mcp)  # in-memory transport: no subprocess, no network

    async with client:
        result = await client.read_resource("data://config")
        for item in result:
            print(item.text)


if __name__ == "__main__":
    asyncio.run(main())
